// src/components/ui/LoanDetail.js
import React, { useState, useEffect } from 'react';
import { loansAPI, repaymentsAPI } from '../../services/api';
import { X, CheckCircle, Clock, AlertCircle, Edit } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import RepaymentModal from './RepaymentModal';

const fmtMoney = (n) => new Intl.NumberFormat('en-US').format(n || 0) + ' FCFA';
const fmtDate = (d) => d ? new Date(d).toLocaleDateString('en-US') : '—';

const scheduleStatusIcon = (s) => {
  if (s === 'PAID') return <CheckCircle size={13} color="var(--success)" />;
  if (s === 'OVERDUE') return <AlertCircle size={13} color="var(--danger)" />;
  return <Clock size={13} color="var(--gray-400)" />;
};

export default function LoanDetail({ loan, onClose }) {
  const { user } = useAuth();
  const [schedule, setSchedule] = useState([]);
  const [repayments, setRepayments] = useState([]);
  const [tab, setTab] = useState('schedule');
  const [payModal, setPayModal] = useState(null); // stores the schedule item
  const [status, setStatus] = useState(loan.status);
  const [updatingStatus, setUpdatingStatus] = useState(false);
  const [msg, setMsg] = useState('');

  const load = async () => {
    try {
      const [s, r] = await Promise.all([
        loansAPI.getSchedule(loan._id),
        repaymentsAPI.getByLoan(loan._id),
      ]);
      setSchedule(s.data.data);
      setRepayments(r.data.data);
    } catch {}
  };

  useEffect(() => { load(); }, [loan._id]);

  const handleStatusUpdate = async (newStatus) => {
    if (!window.confirm(`Change status to ${newStatus}?`)) return;
    setUpdatingStatus(true);
    try {
      await loansAPI.updateStatus(loan._id, newStatus);
      setStatus(newStatus);
      setMsg('Status updated successfully');
    } catch (err) {
      setMsg(err.response?.data?.message || 'Error during update');
    }
    setUpdatingStatus(false);
  };

  const totalPaid = repayments.reduce((s, r) => s + r.amount, 0);
  const remaining = (loan.totalRepayable || 0) - totalPaid;

  return (
    <div className="modal-backdrop" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal fade-in" style={{ maxWidth: 660 }}>
        <div className="modal-header">
          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            <h3>Loan Details</h3>
            {user.role === 'ADMIN' && (
              <div style={{ display: 'flex', alignItems: 'center', gap: 6, background: 'var(--gray-50)', padding: '4px 8px', borderRadius: 8, border: '1px solid var(--gray-200)' }}>
                <Edit size={12} color="var(--gray-400)" />
                <select 
                  style={{ border: 'none', background: 'transparent', fontSize: 11, fontWeight: 600, outline: 'none', cursor: 'pointer' }}
                  value={status} 
                  onChange={(e) => handleStatusUpdate(e.target.value)}
                  disabled={updatingStatus}
                >
                  <option value="ACTIVE">ACTIVE</option>
                  <option value="OVERDUE">OVERDUE</option>
                  <option value="COMPLETED">PAID</option>
                </select>
              </div>
            )}
          </div>
          <button onClick={onClose} className="btn btn-icon btn-outline"><X size={15} /></button>
        </div>
        <div className="modal-body" style={{ padding: '16px 24px' }}>
          {msg && <div className={`alert ${msg.toLowerCase().includes('successfully') ? 'alert-success' : 'alert-danger'}`}>{msg}</div>}

          {/* Summary */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 10, marginBottom: 20 }}>
            {[
              { label: 'Amount', value: fmtMoney(loan.amount) },
              { label: 'Interest', value: fmtMoney(loan.interest) },
              { label: 'Total', value: fmtMoney(loan.totalRepayable) },
              { label: 'Remaining', value: fmtMoney(Math.max(0, remaining)), danger: remaining > 0 },
            ].map(({ label, value, danger }) => (
              <div key={label} style={{ background: danger ? 'var(--danger-light)' : 'var(--gray-50)', borderRadius: 8, padding: '10px 12px', border: '1px solid var(--gray-200)' }}>
                <div style={{ fontSize: 10, color: 'var(--gray-500)', fontWeight: 600, textTransform: 'uppercase', marginBottom: 2 }}>{label}</div>
                <div style={{ fontSize: 13, fontWeight: 700, color: danger ? 'var(--danger)' : 'var(--gray-900)' }}>{value}</div>
              </div>
            ))}
          </div>

          {/* Progress bar */}
          <div style={{ marginBottom: 20 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 11, color: 'var(--gray-500)', marginBottom: 6 }}>
              <span>Progress ({Math.round((totalPaid / (loan.totalRepayable || 1)) * 100)}%)</span>
              <span>{fmtMoney(totalPaid)} paid</span>
            </div>
            <div style={{ background: 'var(--gray-200)', borderRadius: 4, height: 8, overflow: 'hidden' }}>
              <div style={{
                height: '100%', borderRadius: 4,
                background: status === 'COMPLETED' ? 'var(--success)' : status === 'OVERDUE' ? 'var(--danger)' : 'var(--accent)',
                width: `${Math.min(100, Math.round((totalPaid / (loan.totalRepayable || 1)) * 100))}%`,
                transition: 'width 0.5s ease',
              }} />
            </div>
          </div>

          {/* Tabs */}
          <div style={{ display: 'flex', gap: 4, marginBottom: 16, borderBottom: '1px solid var(--gray-200)', paddingBottom: 0 }}>
            {[['schedule', 'Schedule'], ['repayments', 'Payments']].map(([key, label]) => (
              <button key={key} onClick={() => setTab(key)} style={{
                padding: '8px 16px', border: 'none', background: 'transparent',
                fontSize: 13, fontWeight: tab === key ? 600 : 400,
                color: tab === key ? 'var(--primary)' : 'var(--gray-500)',
                borderBottom: tab === key ? '2px solid var(--primary)' : '2px solid transparent',
                cursor: 'pointer', marginBottom: -1,
              }}>{label} ({key === 'schedule' ? schedule.length : repayments.length})</button>
            ))}
          </div>

          {tab === 'schedule' && (
            <div style={{ maxHeight: 300, overflowY: 'auto' }}>
              <table>
                <thead><tr><th>Month</th><th>Amount</th><th>Date</th><th>Status</th><th></th></tr></thead>
                <tbody>
                  {schedule.map((s) => (
                    <tr key={s._id}>
                      <td>Month {s.monthNumber}</td>
                      <td>{fmtMoney(s.amountDue)}</td>
                      <td>{fmtDate(s.dueDate)}</td>
                      <td>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                          {scheduleStatusIcon(s.status)}
                          <span style={{ fontSize: 12 }}>{s.status === 'PAID' ? 'Paid' : s.status === 'OVERDUE' ? 'Overdue' : 'Pending'}</span>
                        </div>
                      </td>
                      <td>
                        {s.status !== 'PAID' && status !== 'COMPLETED' && (
                          <button className="btn btn-accent btn-sm" onClick={() => setPayModal(s)}>
                            Pay
                          </button>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {tab === 'repayments' && (
            <div style={{ maxHeight: 300, overflowY: 'auto' }}>
              {repayments.length === 0 ? (
                <p style={{ color: 'var(--gray-400)', fontSize: 13, textAlign: 'center', padding: 24 }}>No payments recorded</p>
              ) : (
                <table>
                  <thead><tr><th>Amount</th><th>Date</th><th>Note</th></tr></thead>
                  <tbody>
                    {repayments.map((r) => (
                      <tr key={r._id}>
                        <td style={{ fontWeight: 600, color: 'var(--success)' }}>{fmtMoney(r.amount)}</td>
                        <td>{fmtDate(r.paidAt)}</td>
                        <td style={{ color: 'var(--gray-500)' }}>{r.note || '—'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          )}
        </div>

        {payModal && (
          <RepaymentModal 
            loanId={loan._id} 
            scheduleId={payModal._id} 
            onClose={() => setPayModal(null)} 
            onSave={() => {
              setPayModal(null);
              setMsg('Payment recorded successfully');
              load();
            }}
          />
        )}
      </div>
    </div>
  );
}
